<template>
  <div>
    <Combobox
      :model-value="selectedIndex"
      :class="cn('relative w-full', elementWidth)"
      :disabled="disabled"
      @update:model-value="
        (i) => {
          const idx = i == null ? null : Number(i);
          fieldValue = idx == null ? null : allItems[idx].value;
        }
      "
    >
      <ComboboxAnchor as-child>
        <ComboboxTrigger :id="componentField?.name" as-child :disabled="loading">
          <Button variant="outline" class="justify-between [&>span]:truncate h-10 w-full">
            <span v-if="loading">{{ loadingText }}</span>
            <span v-else :class="cn(selectedItem ? '' : 'text-muted-foreground')">{{
              selectedItem ? `${selectedItem.name ?? selectedItem.value}` : placeholder
            }}</span>
            <Spinner v-if="loading" class="!w-5 !h-5" />
            <ChevronsUpDown v-else class="ml-6 h-4 w-4 shrink-0 opacity-50" />
          </Button>
        </ComboboxTrigger>
        <ComboboxCancel class="absolute top-[0.75rem] end-10">
          <X v-if="fieldValue != null" class="h-4 w-4 shrink-0 opacity-50" @click.stop.prevent="fieldValue = null" />
        </ComboboxCancel>
      </ComboboxAnchor>

      <ComboboxList class="max-h-[min(20rem,_calc(var(--reka-combobox-content-available-height)-10px))] relative z-0">
        <div class="sticky top-[-1px] z-50 bg-white rounded-lg">
          <div class="relative w-full items-center">
            <ComboboxInput
              class="pl-9 focus-visible:ring-0 border-0 border-b rounded-none h-10"
              :placeholder="inputPlaceholder"
              :display-value="(v) => ''"
            />
            <span class="absolute start-0 inset-y-0 flex items-center justify-center px-3">
              <Search class="size-4 text-muted-foreground" />
            </span>
          </div>
        </div>

        <ComboboxEmpty> {{ emptyText }} </ComboboxEmpty>

        <ComboboxGroup class="overflow-y-auto">
          <ComboboxItem
            v-for="(item, i) in allItems"
            :key="i"
            :value="i"
            :text-value="item.name ?? stringify(item.value)"
          >
            {{ item.name ?? stringify(item.value) }}

            <ComboboxItemIndicator>
              <Check :class="cn('ml-auto h-4 w-4')" />
            </ComboboxItemIndicator>
          </ComboboxItem>
        </ComboboxGroup>
      </ComboboxList>
    </Combobox>
    <p v-if="error" class="p-2 text-sm text-destructive select-none">{{ error }}</p>
  </div>
</template>

<script lang="ts" setup>
import { Check, ChevronsUpDown, Search, X } from 'lucide-vue-next';
import { Spinner } from '~/assets/icons';
import { cn } from '@/lib/utils';
import { isEqual } from 'lodash';

interface Props {
  items: SelectItem<string | number | Record<string, string[]>>[];
  placeholder?: string;
  inputPlaceholder?: string;
  emptyText?: string;
  elementWidth?: string;
  nullIsAll: boolean;
  componentField: any;
  disabled?: boolean;
  loading?: boolean;
  loadingText?: string;
  error?: string;
}

const props = withDefaults(defineProps<Props>(), {
  placeholder: undefined,
  inputPlaceholder: undefined,
  emptyText: undefined,
  elementWidth: undefined,
  disabled: false,
  loading: false,
  loadingText: 'Loading items...',
  error: undefined,
});

const emit = defineEmits<{ change: [value: string | number | Record<string, string[]> | null] }>();

const fieldValue = computed({
  get: () => props.componentField?.value ?? props.componentField?.modelValue,
  set: (v) => {
    if (props.componentField?.setValue) props.componentField.setValue(v);
    else props.componentField?.onChange?.(v);
    emit('change', v);
  },
});

const selectedIndex = computed<number | null>(() => {
  const v = fieldValue.value;
  if (v == null) return null;
  const idx = allItems.value.findIndex((it) => isEqual(it.value, v));
  return idx >= 0 ? idx : null;
});

const stringify = (v: any) => (typeof v === 'object' ? JSON.stringify(v) : String(v));

const allItems = computed(() => {
  if (props.nullIsAll) {
    return [{ name: props.placeholder, value: null }, ...props.items];
  }
  return props.items;
});

const selectedItem = computed(() => allItems.value.find((item) => isEqual(item.value, fieldValue.value)) ?? null);
</script>

<style scoped lang="scss"></style>
